-export interface GliderState { pos: THREE.Vector3; yaw: number; bank: number }
+export interface GliderState { pos: THREE.Vector3; yaw: number; bank: number; ret: number }   // ret: chiều rẽ đang chốt khi lái về khung (0 = không)
