13:## 2. Mục tiêu
26:   - Có **sàn** và **trần** độ cao. Tới gần ranh giới vùng bay thì dù **tự vòng về** một cách êm, không có tường vô hình làm khựng lại.
     1	/* ============================ Tự khám phá: mô hình bay dù lượn ============================
     2	   Thuần toán học, không đụng cảnh. Hướng bay (cos yaw, 0, −sin yaw), cùng quy ước với `walk` trong views/camera.ts:
     3	   yaw tăng là rẽ trái, bank > 0 là nghiêng trái. Mọi thông số ở CONFIG.explore. */
     4	import * as THREE from 'three';
     5	import { CONFIG } from '../config';
     6	
     7	const C = CONFIG.explore;
     8	
     9	export interface GliderState { pos: THREE.Vector3; yaw: number; bank: number; ret: number }   // ret: chiều rẽ đang chốt khi lái về khung (0 = không)
    10	export interface GliderInput { turn: -1 | 0 | 1; climb: -1 | 0 | 1 }
    11	
    12	/* Trạng thái ban đầu tại điểm cất cánh */
    13	export function exCreate(): GliderState {
    14	  return { pos: new THREE.Vector3(C.takeoff[0], C.takeoff[1], C.takeoff[2]), yaw: C.takeoffYaw, bank: 0, ret: 0 };
    15	}
    16	
    17	const wrapPi = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));
    18	
    19	/* Lái về trong khung khi sát mép. "Hướng vào" n = tổng pháp tuyến hướng vào của các mép nằm trong returnMargin, trọng số theo độ gần.
    20	   Đang bay ra (hướng bay · n < returnEngage) thì bỏ qua phím và lái cố định về n tới khi hướng bay · n >= returnRelease (trễ, hướng rẽ chốt trong s.ret nên không đổi dấu liên tục).
    21	   Chiều rẽ: theo phím người chơi nếu đủ xa mép (vòng tròn bán kính ≈ speed/turnRate không đi ra quá ~2 bán kính, nên giữ A/D chỉ quay tại chỗ, không rung), sát mép (< returnShort) thì rẽ đường ngắn. */
    22	function exTurnEff(s: GliderState, turn: number): number {
    23	  const b = C.bounds, m = C.returnMargin;
    24	  const dx0 = s.pos.x - b.x0, dx1 = b.x1 - s.pos.x, dz0 = s.pos.z - b.z0, dz1 = b.z1 - s.pos.z;
    25	  const d = Math.min(dx0, dx1, dz0, dz1);   // khoảng cách ngắn nhất tới mép khung
    26	  if (d >= m) { s.ret = 0; return turn; }
    27	  const nx = (dx0 < m ? 1 - dx0 / m : 0) - (dx1 < m ? 1 - dx1 / m : 0);   // +X là vào trong khi gần mép x0
    28	  const nz = (dz0 < m ? 1 - dz0 / m : 0) - (dz1 < m ? 1 - dz1 / m : 0);
    29	  const nl = Math.hypot(nx, nz) || 1;
    30	  const dot = (Math.cos(s.yaw) * nx - Math.sin(s.yaw) * nz) / nl;   // hướng bay · hướng vào
    31	  if (s.ret !== 0) { if (dot >= C.returnRelease) { s.ret = 0; return turn; } return s.ret; }
    32	  else if (dot >= C.returnEngage) return turn;
    33	  else {
    34	    const delta = wrapPi(Math.atan2(-nz, nx) - s.yaw);   // yaw hướng vào − yaw hiện tại (>0: rẽ trái là đường ngắn)
    35	    s.ret = turn !== 0 && d >= C.returnShort ? turn : (delta >= 0 ? 1 : -1);
    36	  }
    37	  return s.ret;
    38	}
    39	
    40	/* Một bước mô phỏng: không cấp phát */
    41	export function exStep(s: GliderState, inp: GliderInput, dt: number): void {
    42	  const turn = exTurnEff(s, inp.turn);
    43	  s.bank += (turn * C.bankMax - s.bank) * Math.min(1, C.bankRate * dt);
    44	  s.yaw += C.turnRate * (s.bank / C.bankMax) * dt;
    45	  s.pos.x += Math.cos(s.yaw) * C.speed * dt;
    46	  s.pos.z -= Math.sin(s.yaw) * C.speed * dt;
    47	  s.pos.y = Math.min(C.ceiling, Math.max(C.floor, s.pos.y + inp.climb * C.climbRate * dt));
    48	  const b = C.bounds;   // kẹp cứng: không bao giờ vượt khung
    49	  s.pos.x = Math.min(b.x1, Math.max(b.x0, s.pos.x));
    50	  s.pos.z = Math.min(b.z1, Math.max(b.z0, s.pos.z));
    51	}
    52	
    53	/* Phím giữ → đầu vào lái: A/← trái, D/→ phải, W/↑ lên, S/↓ xuống; hai phím ngược nhau triệt tiêu */
    54	export function exInputFromKeys(keys: Set<string>, out: GliderInput = { turn: 0, climb: 0 }): GliderInput {   // out: đối tượng tái dùng cho đường khung hình (không cấp phát)
    55	  const turn = (keys.has('a') || keys.has('arrowleft') ? 1 : 0) - (keys.has('d') || keys.has('arrowright') ? 1 : 0);
    56	  const climb = (keys.has('w') || keys.has('arrowup') ? 1 : 0) - (keys.has('s') || keys.has('arrowdown') ? 1 : 0);
    57	  out.turn = turn as -1 | 0 | 1; out.climb = climb as -1 | 0 | 1;
    58	  return out;
    59	}

