-      out.e = ok;
-      // 1f giữ A ở góc, hướng ra ngoài
-      s = exCreate(); s.pos.set(C.bounds.x1 - 50, 300, C.bounds.z0 + 50); s.yaw = Math.PI / 4; s.bank = 0; ok = true;
-      let flips = 0, prev = 0;
-      const t = [0];
